/**
 * library-inventory.js — the LIBRARY VIEW (Forest Builder §4.5, the Library
 * Builder's generated front-end doc). "List all the available leaves (and barks
 * and chassis) somewhere" — one canonical, always-fresh listing of every part in
 * the kit by rubric value, with quality + source + which species want it, plus
 * the GAPS (rubric values with no part) and what still needs procuring.
 *
 * Reads the §7.1 part-index (the SSoT) + rubric + dossiers. No writes of its own
 * besides public/library/INVENTORY.md (regenerated by ingest after every run).
 * CLI: node arborist/library-inventory.js
 */
import { readFileSync, writeFileSync, existsSync, readdirSync } from 'fs'
import { join } from 'path'

const RUBRIC = 'arborist/rubric.json'
const PART_INDEX = 'arborist/state/part-index.json'
const DOSSIERS = 'arborist/dossiers'
const OUT = 'public/library/INVENTORY.md'
const readJSON = (p) => JSON.parse(readFileSync(p, 'utf8'))

export function computeInventory() {
  const rubric = readJSON(RUBRIC)
  const parts = existsSync(PART_INDEX) ? readJSON(PART_INDEX).parts || [] : []
  const dossiers = existsSync(DOSSIERS)
    ? readdirSync(DOSSIERS).filter(f => f.endsWith('.json')).map(f => readJSON(join(DOSSIERS, f)))
    : []

  // which rubric value does each dossier WANT, per part-type → for "wanted by" + gaps
  const wantBy = { 'leaf.silhouette': {}, 'bark.type': {} }
  for (const d of dossiers) for (const axis of Object.keys(wantBy)) {
    const t = d.required && d.required[axis] && d.required[axis].target
    if (t) (wantBy[axis][t] = wantBy[axis][t] || []).push(d.key)
  }

  const leafAxis = rubric.axes.find(a => a.id === 'leaf.silhouette')
  const barkAxis = rubric.axes.find(a => a.id === 'bark.type')

  const leaves = parts.filter(p => p.partType === 'leaf').map(p => ({
    pack: p.partId,
    silhouette: p.tags['leaf.silhouette']?.value ?? null,
    rawMorph: p.packMeta?.morphology,
    sizeCm: p.tags['leaf.size']?.value ?? p.packMeta?.naturalSize ?? null,
    quality: p.packMeta?.quality || 'vendor',
    species: p.packMeta?.recommendedSpecies || [],
  })).sort((a, b) => String(a.silhouette).localeCompare(String(b.silhouette)))

  const barks = parts.filter(p => p.partType === 'bark').map(p => ({
    id: p.partId, type: p.tags['bark.type']?.value ?? null, provenance: p.provenance || 'ambientCG (draft quality)',
  }))

  // GAPS: rubric values with no part covering them
  const leafHave = new Set(leaves.map(l => l.silhouette).filter(Boolean))
  const barkHave = new Set(barks.map(b => b.type).filter(Boolean))
  const leafGaps = leafAxis.values.filter(v => !leafHave.has(v))
  const barkGaps = barkAxis.values.filter(v => !barkHave.has(v))

  const chassisByHabit = {}
  for (const p of parts.filter(p => p.partType === 'chassis')) {
    const h = p.tags['chassis.habit']?.value || '(untagged)'
    chassisByHabit[h] = (chassisByHabit[h] || 0) + 1
  }

  return { leaves, barks, leafGaps, barkGaps, chassisByHabit, wantBy, leafSilhouettes: leafAxis.values, barkTypes: barkAxis.values }
}

export function renderInventory(inv) {
  const L = []
  L.push('# Library inventory — all available parts (generated)')
  L.push('')
  L.push('> Auto-generated by `arborist/library-inventory.js` on every ingest. The canonical listing of')
  L.push("> every part in the kit by rubric value, its quality + which species want it, and the GAPS.")
  L.push('> 🟢 vendor = hi-res vendor pack · 🟡 placeholder = wired flat placeholder (Stage-2/3 upgrade) · 🔴 gap = no part.')
  L.push('')

  // ── LEAVES ──
  L.push('## Leaves (by silhouette)')
  L.push('')
  L.push('| silhouette | pack | size | quality | recommended species |')
  L.push('|---|---|---|---|---|')
  for (const v of inv.leafSilhouettes) {
    const packs = inv.leaves.filter(l => l.silhouette === v)
    if (packs.length === 0) {
      const want = inv.wantBy['leaf.silhouette'][v] || []
      L.push(`| **${v}** | 🔴 GAP | — | — | ${want.join(', ') || '—'} |`)
    } else {
      for (const p of packs) {
        const q = p.quality === 'vendor' ? '🟢 vendor' : `🟡 ${p.quality}`
        L.push(`| ${v} | ${p.pack} | ${p.sizeCm ?? '?'}cm | ${q} | ${(p.species || []).join(', ') || '—'} |`)
      }
    }
  }
  // unresolved (season/variant packs that aren't a silhouette)
  const unresolved = inv.leaves.filter(l => !l.silhouette)
  if (unresolved.length) {
    L.push('')
    L.push(`_Non-silhouette packs (season/variant, not a single-leaf shape): ${unresolved.map(u => `${u.pack}(${u.rawMorph})`).join(', ')}_`)
  }
  L.push('')
  L.push(`**Leaf gaps (no pack): ${inv.leafGaps.length ? inv.leafGaps.join(', ') : 'none'}.**`)
  L.push('')

  // ── BARKS ──
  L.push('## Barks (by type)')
  L.push('')
  L.push('| type | asset | provenance | wanted by |')
  L.push('|---|---|---|---|')
  for (const v of inv.barkTypes) {
    const got = inv.barks.filter(b => b.type === v)
    const want = inv.wantBy['bark.type'][v] || []
    if (got.length === 0) L.push(`| **${v}** | 🔴 GAP | — | ${want.join(', ') || '—'} |`)
    else for (const b of got) L.push(`| ${v} | ${b.id} | ${b.provenance} | ${want.join(', ') || '—'} |`)
  }
  L.push('')
  L.push(`**Bark gaps (no asset): ${inv.barkGaps.length ? inv.barkGaps.join(', ') : 'none'}.**`)
  L.push('')

  // ── CHASSIS (summary) ──
  L.push('## Chassis (by habit) — count')
  L.push('')
  L.push(Object.entries(inv.chassisByHabit).sort((a, b) => b[1] - a[1]).map(([h, n]) => `${h}: ${n}`).join(' · '))
  L.push('')
  return L.join('\n')
}

/** Regenerate public/library/INVENTORY.md (called by ingest). */
export function writeInventory() {
  const md = renderInventory(computeInventory())
  writeFileSync(OUT, md)
  return md
}

if (process.argv[1] && process.argv[1].endsWith('library-inventory.js')) {
  console.log(renderInventory(computeInventory()))
}
